class CallCounter:
    """Per-factory call accounting.

    The old module-level COUNTS was shared by every factory, so a second factory
    inherited (and could exhaust) another factory's budget.  One instance per
    factory, keyed by handler name, keeps limits per handler *and* per factory.
    """

    def __init__(self):
        self._counts = {}

    def consume(self, name, limit):
        count = self._counts.get(name, 0) + 1
        self._counts[name] = count
        if count > limit:
            raise RuntimeError("call limit exceeded")

