from .state import CallCounter


def make_processors(specs):
    processors = {}
    counter = CallCounter()          # a fresh factory call is fresh state

    for spec in specs:
        name = spec["name"]
        limit = spec["limit"]
        offset = spec["offset"]

        if limit <= 0:
            raise ValueError(f"limit must be positive, got {limit!r}")
        if name in processors:
            raise ValueError(f"duplicate handler name: {name!r}")

        # Bind the values, not the loop variable and not the caller's dict, so
        # each handler keeps the configuration it was built with.
        def process(value, _name=name, _limit=limit, _offset=offset, _counter=counter):
            _counter.consume(_name, _limit)
            return value + _offset

        processors[name] = process
    return processors
